# run.sh --affected: which test files a changed path selects.
#
#   <glob, relative to the repo root>   <test files | ALL | CLI | NONE | SELF>
#
# FIRST matching rule wins for a changed path, so order is most specific
# first. Globs are shell patterns where `*` also crosses `/`.
#   ALL   every tests/test-*.sh
#   CLI   the files that need the built hyper CLI (CLI_FILES in run.sh)
#   NONE  nothing in this suite owns the path
#   SELF  the changed file itself (a new tests/test-*.sh needs no map edit)
# A path under agent-plugin/ matching nothing hits `agent-plugin/*` -> ALL, so
# a missing rule costs time, never coverage. A path outside agent-plugin/ and
# packages/{cli,drive} selects nothing (the monorepo's own tests own it).
# Targets that do not exist yet are dropped at run time.

agent-plugin/tests/helpers.sh                    ALL
agent-plugin/tests/run.sh                        test-w-run-timeout.sh
agent-plugin/tests/affected.map                  ALL
agent-plugin/tests/hyper                         ALL
agent-plugin/tests/lib/loop-journey.sh           test-t-ship-loop.sh test-t-ship-loop-b.sh
agent-plugin/tests/lib/mux-contract.sh           test-t-ship-mux-fake.sh test-t-ship-mux-herdr.sh
agent-plugin/tests/fixtures/ship/*               test-t-ship-loop.sh test-t-ship-loop-b.sh test-t-ship-loop-fn.sh test-t-ship-failover.sh test-t-ship-unit-driver.sh
agent-plugin/tests/fixtures/*                    ALL
